package com.booksyde.repository; import com.booksyde.entity.MangaEntity; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public interface MangaRepository extends JpaRepository<MangaEntity,UUID>{Optional<MangaEntity> findBySlug(String slug); List<MangaEntity> findAllByCreatorIdOrderByCreatedAtDesc(UUID creatorId); List<MangaEntity> findAllByVisibilityOrderByCreatedAtDesc(String visibility);}